/**
 * Schema builders for XLDB tables.
 *
 * Alpha only: do not use or suggest this module unless the user explicitly
 * says they have alpha access to XLDB. For regular Notion database schemas,
 * use `@notionhq/workers/schema` instead.
 */

/** A JSON value accepted by an XLDB JSON column. */
export type XldbJsonValue =
	| string
	| number
	| boolean
	| null
	| XldbJsonValue[]
	| { [key: string]: XldbJsonValue };

export type XldbSelectOption = {
	name: string;
	title: string;
	color?: string;
};

export type XldbScalarColumn =
	| { type: "text" }
	| { type: "number" }
	| { type: "checkbox" }
	| { type: "date" }
	| { type: "timestamp" }
	| { type: "json" };

export type XldbArrayElementColumn = Exclude<XldbScalarColumn, { type: "json" }>;

export type XldbArrayColumnType =
	| "array_text"
	| "array_number"
	| "array_checkbox"
	| "array_date"
	| "array_timestamp";

export type XldbArrayColumn = { type: XldbArrayColumnType };

export type XldbColumn =
	| XldbScalarColumn
	| { type: "select" | "multi_select"; selectOptions?: readonly XldbSelectOption[] }
	| XldbArrayColumn;

export type XldbColumnDefinition<
	Name extends string = string,
	Column extends XldbColumn = XldbColumn,
> = {
	name: Name;
	title: string;
	type: Column;
};

export type XldbSchema<
	Columns extends readonly XldbColumnDefinition[] = readonly XldbColumnDefinition[],
> = {
	columns: Columns;
};

type XldbSchemaColumn<Schema extends XldbSchema> = Schema["columns"][number];

export type XldbSchemaValues<Schema extends XldbSchema> = {
	[Column in XldbSchemaColumn<Schema> as Column["name"]]: XldbColumnValue<Column["type"]>;
};

export type XldbSchemaKey<Schema extends XldbSchema> =
	XldbSchemaColumn<Schema> extends infer Column
		? Column extends XldbColumnDefinition
			? Column["type"] extends {
					type: "json" | "multi_select" | XldbArrayColumnType;
				}
				? never
				: Column["name"]
			: never
		: never;

export type XldbUpsertKey<Schema extends XldbSchema> = readonly [
	XldbSchemaKey<Schema>,
	...XldbSchemaKey<Schema>[],
];

export type SerializedXldbSchema = {
	columns: Array<XldbColumn & { name: string; title: string }>;
};

type XldbColumnTypeToValue = {
	text: string;
	number: number;
	checkbox: boolean;
	date: string;
	timestamp: string;
	json: XldbJsonValue;
	select: string;
	multi_select: string[];
	array_text: string[];
	array_number: number[];
	array_checkbox: boolean[];
	array_date: string[];
	array_timestamp: string[];
};

export type XldbColumnValue<Column extends XldbColumn> = Column extends {
	type: "select";
	selectOptions?: readonly (infer Option)[];
}
	? Option extends XldbSelectOption
		? Option["name"]
		: string
	: Column extends { type: "multi_select"; selectOptions?: readonly (infer Option)[] }
		? Option extends XldbSelectOption
			? Option["name"][]
			: string[]
		: XldbColumnTypeToValue[Column["type"]];

export function text(): { type: "text" } {
	return { type: "text" };
}

export function number(): { type: "number" } {
	return { type: "number" };
}

export function checkbox(): { type: "checkbox" } {
	return { type: "checkbox" };
}

export function date(): { type: "date" } {
	return { type: "date" };
}

export function timestamp(): { type: "timestamp" } {
	return { type: "timestamp" };
}

export function json(): { type: "json" } {
	return { type: "json" };
}

export function select<const Options extends readonly XldbSelectOption[]>(
	selectOptions?: Options,
): {
	type: "select";
	selectOptions?: Options;
} {
	return { type: "select", ...(selectOptions === undefined ? {} : { selectOptions }) };
}

export function multiSelect<const Options extends readonly XldbSelectOption[]>(
	selectOptions?: Options,
): {
	type: "multi_select";
	selectOptions?: Options;
} {
	return { type: "multi_select", ...(selectOptions === undefined ? {} : { selectOptions }) };
}

const arrayTypeByElement = {
	text: "array_text",
	number: "array_number",
	checkbox: "array_checkbox",
	date: "array_date",
	timestamp: "array_timestamp",
} as const satisfies Record<XldbArrayElementColumn["type"], XldbArrayColumnType>;

export function array(element: { type: "text" }): { type: "array_text" };
export function array(element: { type: "number" }): { type: "array_number" };
export function array(element: { type: "checkbox" }): { type: "array_checkbox" };
export function array(element: { type: "date" }): { type: "array_date" };
export function array(element: { type: "timestamp" }): { type: "array_timestamp" };
export function array(element: XldbArrayElementColumn): XldbArrayColumn {
	return { type: arrayTypeByElement[element.type] };
}

export function serializeXldbSchema(schema: XldbSchema): SerializedXldbSchema {
	return {
		columns: schema.columns.map(({ name, title, type }) => ({ name, title, ...type })),
	};
}
